"""Typed source dossier: parser mode writers, quoted units and ordinary entry."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA026,0xA027,'data','Maiuscola pendente: stato persistente distinto da spazio, CR e forzatura'),(0xA7D0,0xA7EA,'code','Nome proprio: selezione del bit e caso YOU'),(0xA7EA,0xA7EB,'data','Latch del nome proprio:0 oppure1, azzerato per entità non persona'),(0xA815,0xA82F,'code','Emissione del nome: OR indiretto dopo la parola, anche invisibile'),(0xA887,0xA8AC,'code','Dizionario in contesto70: writer1 dopo il separatore iniziale'),(0xA9B7,0xAA71,'code','Buffer e normalizzazione: maiuscola decisa quando la parola viene scaricata'),(0xA419,0xA476,'code','Importi: writer0 soltanto nei rami con D-punto o scellini esatti'),(0xD3E8,0xD448,'code','Tuple nome: propagazione della maiuscola tra qualificatori e sostantivo'),(0xA851,0xA852,'data','Forzatura delle maiuscole: stato diverso daA026'),(0xA852,0xA85C,'code','Toggle della forzatura: A026 resta indipendente')]
notes={0xA026:'Byte iniziale1 estratto dal payload. Non ricavarlo dalle lettere maiuscole già visualizzate. OldSAVE assente restaunknown fino a un writer dimostrato.',0xA7D1:'A7D0 azzera il latch del nome proprio prima di esaminare il bit7 del descrittore.',0xA7E3:'YOU/09EE è un nome con bit proprio ma non propaga la maiuscola: ritorna con latch0.',0xA7E6:'Altri nomi con bit7 impostano il latch1. D3F9 può azzerarlo per entità senza attributo persona.',0xA7EA:'Dato mutabile0/1 del chiamante dei nomi. Non è un opcode. Il nuovo runtime ricava il bit dal referente, non installa un valore registrato diA026.',0xA820:'Offset nullo: ritorna prima diA887 e prima dell’OR. Nessun writerA82C per la parola inesistente.',0xA821:'Il separatore diA887 scarica la parola precedente prima di accodare la nuova. Solo dopo avviene la propagazione del latch.',0xA82C:'Quinto writer, indiretto: A026 |= A7EA. Si esegue anche se A887 ha soppresso i pixel. OR1 non trasforma255 in1 e non rende noto un vecchioSAVE assente.',0xA8A9:'Contesto70, offset nonzero e output non soppresso: scrive1 dopo lo spazio iniziale e prima delle lettere ancora nel buffer.',0xA9D4:'Backspace modifica soltanto il buffer, non scriveA026. La classificazione dei caratteri superstiti rimane nel SAVE.',0xA9FD:'AA14 normalizza i caratteri solo nello svuotamento del buffer; non scrivere il flag quando si accoda una lettera.',0xAA36:'Questo writer riguardaA025, NONA026: un CR da solo conserva la maiuscola pendente.',0xAA4C:'Punto e virgoletta già normalizzati scrivono1 anche se C1E1 scarterà il disegno.',0xAA59:'A851 forza le lettere. PerA026 il risultato dopo una lettera è comunque0, indipendentemente dalla forzatura.',0xAA66:'Lettera con maiuscola richiesta o forzata: scrive0. Nel ramo senza writer il flag era già0; il risultato funzionale è0 per ogni lettera ASCII.',0xA419:'HL contiene la valuta codificata: bit7 basso è metadato, non parte dell’importo. Le ABI passano encodeMoney(pence), non il numero grezzo.',0xA43B:'Sterline intere: ritorna senzaA464. Non azzerare per ogni importo.',0xA45C:'Scellini con resto in pence: ritorna senzaA464.',0xA464:'Writer0 dopo D-punto o trattino degli scellini; la cifra può essere ancora nel buffer. Un punto scaricato più tardi ristabilisce1.',0xD3F9:'Entità senza bit6 nell’attributo: azzera il latch proprio, indipendentemente dal bit7 del sostantivo.',0xD438:'Sostantivo finale: può rimanere nel buffer dopo l’ultimo OR, fino al separatore del chiamante.',0xA857:'ScriveA851, nonA026. Il nuovo contratto non pubblica un valore diA851 come ingresso casuale.'}
lines=['; Dossier offline: istruzioni e dati tipizzati, verificati e riassellati sul payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/output-capitalization';root.mkdir(exist_ok=True);(root/'output-capitalization.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=155)for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
